#include "tests/support/socket/node_string_test_fixture.hpp"
using namespace node_string_test;
namespace {
void entry_and_aliases(){
    {Fixture f;f.text("untouched",0x204);const auto before=f.bytes;f.omitted={{Fixture::pair+16,8},{Fixture::input,128}};f.refresh();check(f.call()==Fixture::input&&f.get(Fixture::pair,4)==0x204,"flag100-clear returns live start without end read or flags mask");check(f.bytes==before&&f.characters.calls.empty()&&f.parser.calls.empty(),"early path performs no text/primitive operation");}
    {Fixture f;f.set(Fixture::pair,0x100,4);f.set(Fixture::pair+8,0xdeadbeef);f.set(Fixture::pair+16,Fixture::input);check(f.call()==0xdeadbeef&&f.bytes[0]==0&&f.get(Fixture::pair,4)==0,"XOR result0 skips start read/first-phase terminator but retains initial end NUL");}
    {Fixture f;f.text("abc",0x301);f.set(Fixture::pair+16,Fixture::pair+1);f.call();check(f.get(Fixture::pair,4)==0&&f.bytes[0]==0,"end store aliases flags before live XOR and first-pass branch");}
    {Fixture f;f.text("abc");f.omitted={{Fixture::input+3,1}};f.refresh();unmapped([&]{f.call();});check(f.get(Fixture::pair,4)==0x101&&f.bytes[0]=='a',"failed initial end store precedes XOR and all body writes");}
    {Fixture f;f.text("abc",0x80000300U);check(f.call()==Fixture::input&&f.result()=="abc"&&f.get(Fixture::pair,4)==0x200,"nonzero unknown flags still execute first pass and final live AND200");}
    {Fixture f;f.text("abc");f.set(Fixture::pair+8,Fixture::input+3);check(f.call()==Fixture::input+3&&f.bytes[3]==0&&f.get(Fixture::pair,4)==0,"empty first-phase range still commits output terminator");}
}
void newline_and_entities(){
    struct Case{std::string_view in,out;};const std::array cases{Case{"a\rb","a\nb"},Case{"a\nb","a\nb"},Case{"a\r\nb","a\nb"},Case{"a\n\rb","a\nb"},Case{"\r\n\n\r\r","\n\n\n"}};
    for(auto c:cases){Fixture f;f.text(c.in,0x102);check(f.call()==Fixture::input&&f.result()==c.out,"CR,LF,CRLF,LFCR normalize with exact advancement");check(f.characters.calls.empty()&&f.parser.calls.empty()&&f.lower.decodes.empty(),"newline-only branch never enters classifier/entity primitives");}
    const std::array<std::string_view,5> names{"quot","amp","apos","lt","gt"};const std::array<char,5> expected{'"','&','\'','<','>'};
    for(unsigned i=0;i<5;++i){Fixture f;const std::string text="x&"+std::string(names[i])+";y";f.text(text);check(f.call()==Fixture::input&&f.result()==std::string("x")+expected[i]+"y","exact retained five entity rows decode one replacement byte");check(f.parser.calls.size()==i+1&&f.lower.decodes.empty(),"named entity compares tables in native order without numeric decode");}
    for(auto value:{std::string_view("\r\n&bogus;Z"),std::string_view("\r\n&quotZ")}){Fixture f;f.text(value,0x103);f.call();const std::string expected_text=value.find("bogus")!=std::string_view::npos?"\n\nbogus;Z":"\n\nquotZ";check(f.result()==expected_text,"unknown/missing-semicolon entity skips store and preserves stale compacted destination byte");check(f.parser.calls.size()==5,"unknown named entity tries all five entries");}
    {Fixture f;f.text("&x;!");f.parser.hook=[&](const auto& c){check(c.count==4,"compare receives original signed row length before callback");f.set(Fixture::table+8,1,4);f.set(Fixture::table+12,'R',1);return 0;};f.call();check(f.result()=="R!"&&f.parser.calls.size()==1,"semicolon and replacement reload live table fields after compare callback");}
    {Fixture f;f.text("&x;!");f.set(Fixture::table+8,0xffffffffU,4);f.parser.hook=[&](const auto& c){check(c.count==UINT64_MAX,"named compare count sign extends DWORD rather than zero extends");throw Failure{};return 0;};fails([&]{f.call();});check(f.get(Fixture::pair,4)==1&&f.bytes[4]==0,"compare failure preserves initial terminator/XOR prefix without final flag mask");}
    {Fixture f;f.text("&amp;tail");f.parser.hook=[&](const auto& c){if(c.right!=Fixture::names+8)return 1;f.set(Fixture::pair+16,Fixture::input+5);f.set(Fixture::pair,0x200,4);return 0;};f.call();check(f.result()=="&"&&f.get(Fixture::pair,4)==0x200,"loop rechecks live end and final live flags after primitive callback");}
    {Fixture f;f.text(std::string(41,'a'));f.extras={{Fixture::table+8,std::span(f.bytes).first(4)}};f.refresh();f.set(Fixture::table+8,38,4);f.set(Fixture::input+39,';',1);f.set(Fixture::table+12,4,1);f.parser.hook=[](const auto& c){check(c.count==38,"physical length/output alias begins with supplied bounded compare count38");return 0;};f.call();check(f.result()==std::string(1,'\x04')+std::string(33,'a')+";a","replacement store aliases row length; cursor advance rereads new DWORD4 and advances6 rather than cached40");}
}
void numeric_boundaries(){
    {Fixture f;f.text("&#42;&#42;z");f.lower.decode_hook=[&](auto p,auto b,auto& n){check(n==0&&std::all_of(b.begin(),b.end(),[](auto v){return v==0;}),"each numeric call receives ten reset bytes and zero count");b[0]=0xe2;b[1]=0x82;b[2]=0xac;n=3;return p+5;};f.call();check(f.result()==std::string("\xe2\x82\xac\xe2\x82\xacz")&&f.lower.copies.size()==2,"successful numeric boundary copies emitted bytes and advances separate cursors");check(f.lower.copies[0].count==3&&f.lower.copies[1].output==Fixture::input+3,"numeric copy receives cached signed length and output address");}
    {Fixture f;f.text("&#42;");f.lower.decode_hook=[&](auto p,auto,auto& n){n=9;f.set(p,'X',1);return std::uintptr_t{0};};f.call();check(f.result()=="X#42;"&&f.lower.copies.empty(),"numeric failure reloads fresh source byte rather than cached ampersand");}
    {Fixture f;f.text("&#42;");f.lower.decode_hook=[](auto p,auto,auto& n){n=-1;return p+5;};fails([&]{f.call();});check(f.lower.copies.size()==1&&f.lower.copies[0].count==UINT64_MAX,"negative numeric count sign extends before mandatory bounded copy failure");check(f.get(Fixture::pair,4)==1&&f.bytes[5]==0&&f.bytes[0]=='&',"copy failure retains end/XOR prefix without invented rollback or final AND");}
    {Fixture f;f.text("&#42;Z");f.lower.decode_hook=[](auto p,auto b,auto& n){b[0]='Q';n=1;return p+5;};f.lower.copy_hook=[&](const auto&){f.set(Fixture::pair+16,Fixture::input+5);f.set(Fixture::pair,0x204,4);};f.call();check(f.result()=="Q"&&f.get(Fixture::pair,4)==0x200,"copy callback affects live loop end and later whitespace/final flags");check(!f.characters.calls.empty(),"whitespace stage sees flags set by copy callback");}
}
void whitespace_and_live_callbacks(){
    for(auto value:{std::string_view("  a\t\t b \n"),std::string_view("\t\r\n"),std::string_view("a"),std::string_view("")}){Fixture f;f.text(value,0x104);const auto result=f.call();const auto expected=value=="  a\t\t b \n"?"a b":value=="a"?"a":"";check(f.result(result)==expected,"ASCII whitespace trims leading/trailing and compacts internal runs");check(f.get(Fixture::pair+8)==result&&f.get(Fixture::pair,4)==0,"leading start publication and final flag clear remain visible");}
    {Fixture f;f.text(std::string("\x80 \x81",3),0x104);f.call();check(f.result()==std::string("\x80 \x81",3)&&std::none_of(f.characters.calls.begin(),f.characters.calls.end(),[](auto b){return b>=0x80;}),"high-bit bytes bypass classifier in both whitespace loops");}
    {Fixture f;f.text("",0x104);f.call();check(f.characters.calls==std::vector<std::uint32_t>{0},"leading whitespace loop classifies NUL once without an invented zero guard");}
    {Fixture f;f.text("a b",0x104);f.call();check(f.characters.calls==std::vector<std::uint32_t>{'a','a',' ',' ','b'},"outer whitespace classification and fresh inner scan retain duplicate native calls");}
    {Fixture f;f.text("ab",0x104);unsigned call=0;f.characters.hook=[&](auto){if(++call==2)f.set(Fixture::input,'Z',1);return 0;};f.call();check(f.result()=="Zb","copy reloads source byte after cached outer classification callback");}
    {Fixture f;f.text(" a",0x104);f.characters.hook=[&](auto b){if(b=='a')f.set(Fixture::pair,0x201,4);return parse_entry_test::controlled_space(b);};check(f.call()==Fixture::input+1&&f.get(Fixture::pair,4)==0x200,"whitespace callback mutation survives final live AND200 and returned published start");}
    {Fixture f;f.text("a b",0x104);f.characters.hook=[](auto){throw Failure{};return 0;};fails([&]{f.call();});check(f.bytes[3]==0&&f.get(Fixture::pair,4)==4,"classifier failure retains first-pass terminator/XOR without final flags clear");}
}
}
int main(){try{entry_and_aliases();newline_and_entities();numeric_boundaries();whitespace_and_live_callbacks();std::cout<<"PASS: "<<checks<<" node-string core checks; live flags/end/table fields,unknown-entity no-store,numeric signed count/newline/whitespace ordering and failure prefixes; decoder/copy/compare/classifier/nativeABI open\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL after "<<checks<<" checks\n";return 1;}}
